-- DEV-ONLY sample data for milestones, milestone-tagged documents and weekly progress (V5 tables).
-- Separate from V1000 so dev databases that already applied V1000 keep a matching checksum.
-- Same time convention as V1000: LOCALTIMESTAMP, relative to when the seed runs.

-- ---------------------------------------------------------------- milestones (Fall2026)

-- ---------------------------------------------------------------- tag V1000's documents with milestones
UPDATE artifact_submissions SET milestone_id = 'e0000000-0000-0000-0000-000000000002', submitted_by = '30000000-0000-0000-0000-000000000001'
    WHERE id IN ('d0000000-0000-0000-0000-000000000001', 'd0000000-0000-0000-0000-000000000002');
UPDATE artifact_submissions SET milestone_id = 'e0000000-0000-0000-0000-000000000004', submitted_by = '30000000-0000-0000-0000-000000000004'
    WHERE id = 'd0000000-0000-0000-0000-000000000003';
UPDATE artifact_submissions SET milestone_id = 'e0000000-0000-0000-0000-000000000002', submitted_by = '30000000-0000-0000-0000-000000000006'
    WHERE id = 'd0000000-0000-0000-0000-000000000004';
UPDATE artifact_submissions SET milestone_id = 'e0000000-0000-0000-0000-000000000003', submitted_by = '30000000-0000-0000-0000-000000000010'
    WHERE id = 'd0000000-0000-0000-0000-000000000005';

